def test_groie():
    cfg = dict(roi_layer=dict(type='RoIAlign', output_size=7, sampling_ratio=2), out_channels=256, featmap_strides=[4, 8, 16, 32], pre_cfg=dict(type='ConvModule', in_channels=256, out_channels=256, kernel_size=5, padding=2, inplace=False), post_cfg=dict(type='ConvModule', in_channels=256, out_channels=256, kernel_size=5, padding=2, inplace=False))
    groie = GenericRoIExtractor(**cfg)
    feats = (torch.rand((1, 256, 200, 336)), torch.rand((1, 256, 100, 168)), torch.rand((1, 256, 50, 84)), torch.rand((1, 256, 25, 42)))
    rois = torch.tensor([[0.0, 587.8285, 52.1405, 886.2484, 341.5644]])
    res = groie(feats, rois)
    assert res.shape == torch.Size([1, 256, 7, 7])
    cfg = dict(roi_layer=dict(type='RoIAlign', output_size=7, sampling_ratio=2), out_channels=256, featmap_strides=[4, 8, 16, 32])
    groie = GenericRoIExtractor(**cfg)
    feats = (torch.rand((1, 256, 200, 336)), torch.rand((1, 256, 100, 168)), torch.rand((1, 256, 50, 84)), torch.rand((1, 256, 25, 42)))
    rois = torch.tensor([[0.0, 587.8285, 52.1405, 886.2484, 341.5644]])
    res = groie(feats, rois)
    assert res.shape == torch.Size([1, 256, 7, 7])
    cfg = dict(aggregation='concat', roi_layer=dict(type='RoIAlign', output_size=7, sampling_ratio=2), out_channels=256 * 4, featmap_strides=[4, 8, 16, 32])
    groie = GenericRoIExtractor(**cfg)
    feats = (torch.rand((1, 256, 200, 336)), torch.rand((1, 256, 100, 168)), torch.rand((1, 256, 50, 84)), torch.rand((1, 256, 25, 42)))
    rois = torch.tensor([[0.0, 587.8285, 52.1405, 886.2484, 341.5644]])
    res = groie(feats, rois)
    assert res.shape == torch.Size([1, 1024, 7, 7])
    with pytest.raises(AssertionError):
        cfg = dict(aggregation='not support', roi_layer=dict(type='RoIAlign', output_size=7, sampling_ratio=2), out_channels=1024, featmap_strides=[4, 8, 16, 32])
        _ = GenericRoIExtractor(**cfg)
    cfg = dict(aggregation='concat', roi_layer=dict(type='RoIAlign', output_size=7, sampling_ratio=2), out_channels=256 * 5, featmap_strides=[4, 8, 16, 32])
    groie = GenericRoIExtractor(**cfg)
    feats = (torch.rand((1, 256, 200, 336)), torch.rand((1, 256, 100, 168)), torch.rand((1, 256, 50, 84)), torch.rand((1, 256, 25, 42)))
    rois = torch.tensor([[0.0, 587.8285, 52.1405, 886.2484, 341.5644]])
    with pytest.raises(AssertionError):
        _ = groie(feats, rois)

def test_csp_darknet_backbone():
    with pytest.raises(ValueError):
        CSPDarknet(frozen_stages=6)
    with pytest.raises(AssertionError):
        CSPDarknet(out_indices=[6])
    frozen_stages = 1
    model = CSPDarknet(frozen_stages=frozen_stages)
    model.train()
    for mod in model.stem.modules():
        for param in mod.parameters():
            assert param.requires_grad is False
    for i in range(1, frozen_stages + 1):
        layer = getattr(model, f'stage{i}')
        for mod in layer.modules():
            if isinstance(mod, _BatchNorm):
                assert mod.training is False
        for param in layer.parameters():
            assert param.requires_grad is False
    model = CSPDarknet(norm_eval=True)
    model.train()
    assert check_norm_state(model.modules(), False)
    model = CSPDarknet(arch='P5', widen_factor=0.25, out_indices=range(0, 5))
    model.train()
    imgs = torch.randn(1, 3, 64, 64)
    feat = model(imgs)
    assert len(feat) == 5
    assert feat[0].shape == torch.Size((1, 16, 32, 32))
    assert feat[1].shape == torch.Size((1, 32, 16, 16))
    assert feat[2].shape == torch.Size((1, 64, 8, 8))
    assert feat[3].shape == torch.Size((1, 128, 4, 4))
    assert feat[4].shape == torch.Size((1, 256, 2, 2))
    model = CSPDarknet(arch='P6', widen_factor=0.25, out_indices=range(0, 6), spp_kernal_sizes=(3, 5, 7))
    model.train()
    imgs = torch.randn(1, 3, 128, 128)
    feat = model(imgs)
    assert feat[0].shape == torch.Size((1, 16, 64, 64))
    assert feat[1].shape == torch.Size((1, 32, 32, 32))
    assert feat[2].shape == torch.Size((1, 64, 16, 16))
    assert feat[3].shape == torch.Size((1, 128, 8, 8))
    assert feat[4].shape == torch.Size((1, 192, 4, 4))
    assert feat[5].shape == torch.Size((1, 256, 2, 2))
    model = CSPDarknet(widen_factor=0.125, act_cfg=dict(type='ReLU'), out_indices=range(0, 5))
    model.train()
    imgs = torch.randn(1, 3, 64, 64)
    feat = model(imgs)
    assert len(feat) == 5
    assert feat[0].shape == torch.Size((1, 8, 32, 32))
    assert feat[1].shape == torch.Size((1, 16, 16, 16))
    assert feat[2].shape == torch.Size((1, 32, 8, 8))
    assert feat[3].shape == torch.Size((1, 64, 4, 4))
    assert feat[4].shape == torch.Size((1, 128, 2, 2))
    model = CSPDarknet(widen_factor=0.125, out_indices=range(0, 5))
    for m in model.modules():
        if is_norm(m):
            assert isinstance(m, _BatchNorm)
    model.train()
    imgs = torch.randn(1, 3, 64, 64)
    feat = model(imgs)
    assert len(feat) == 5
    assert feat[0].shape == torch.Size((1, 8, 32, 32))
    assert feat[1].shape == torch.Size((1, 16, 16, 16))
    assert feat[2].shape == torch.Size((1, 32, 8, 8))
    assert feat[3].shape == torch.Size((1, 64, 4, 4))
    assert feat[4].shape == torch.Size((1, 128, 2, 2))
    arch_ovewrite = [[32, 56, 3, True, False], [56, 224, 2, True, False], [224, 512, 1, True, False]]
    model = CSPDarknet(arch_ovewrite=arch_ovewrite, widen_factor=0.25, out_indices=(0, 1, 2, 3))
    model.train()
    imgs = torch.randn(1, 3, 32, 32)
    feat = model(imgs)
    assert len(feat) == 4
    assert feat[0].shape == torch.Size((1, 8, 16, 16))
    assert feat[1].shape == torch.Size((1, 14, 8, 8))
    assert feat[2].shape == torch.Size((1, 56, 4, 4))
    assert feat[3].shape == torch.Size((1, 128, 2, 2))

def is_block(modules):
    """Check if is ResNet building block."""
    if isinstance(modules, (BasicBlock, Bottleneck, BottleneckX, Bottle2neck, SimplifiedBasicBlock)):
        return True
    return False

def is_norm(modules):
    """Check if is one of the norms."""
    if isinstance(modules, (GroupNorm, _BatchNorm)):
        return True
    return False

def check_norm_state(modules, train_state):
    """Check if norm layer is in correct train state."""
    for mod in modules:
        if isinstance(mod, _BatchNorm):
            if mod.training != train_state:
                return False
    return True

def test_detectorrs_resnet_backbone():
    detectorrs_cfg = dict(depth=50, num_stages=4, out_indices=(0, 1, 2, 3), frozen_stages=1, norm_cfg=dict(type='BN', requires_grad=True), norm_eval=True, style='pytorch', conv_cfg=dict(type='ConvAWS'), sac=dict(type='SAC', use_deform=True), stage_with_sac=(False, True, True, True), output_img=True)
    'Test init_weights config'
    with pytest.raises(AssertionError):
        DetectoRS_ResNet(**detectorrs_cfg, pretrained='Pretrained', init_cfg='Pretrained')
    with pytest.raises(AssertionError):
        DetectoRS_ResNet(**detectorrs_cfg, pretrained=None, init_cfg=['Pretrained'])
    with pytest.raises(KeyError):
        DetectoRS_ResNet(**detectorrs_cfg, pretrained=None, init_cfg=dict(checkpoint='Pretrained'))
    with pytest.raises(AssertionError):
        DetectoRS_ResNet(**detectorrs_cfg, pretrained=None, init_cfg=dict(type='Trained'))
    with pytest.raises(TypeError):
        model = DetectoRS_ResNet(**detectorrs_cfg, pretrained=['Pretrained'], init_cfg=None)
        model.init_weights()

def test_renext_bottleneck():
    with pytest.raises(AssertionError):
        BottleneckX(64, 64, groups=32, base_width=4, style='tensorflow')
    block = BottleneckX(64, 64, groups=32, base_width=4, stride=2, style='pytorch')
    assert block.conv2.stride == (2, 2)
    assert block.conv2.groups == 32
    assert block.conv2.out_channels == 128
    dcn = dict(type='DCN', deform_groups=1, fallback_on_stride=False)
    with pytest.raises(AssertionError):
        BottleneckX(64, 64, groups=32, base_width=4, dcn=dcn, conv_cfg=dict(type='Conv'))
    BottleneckX(64, 64, dcn=dcn)
    block = BottleneckX(64, 16, groups=32, base_width=4)
    x = torch.randn(1, 64, 56, 56)
    x_out = block(x)
    assert x_out.shape == torch.Size([1, 64, 56, 56])
    plugins = [dict(cfg=dict(type='GeneralizedAttention', spatial_range=-1, num_heads=8, attention_type='0010', kv_stride=2), stages=(False, False, True, True), position='after_conv2')]
    block = BottleneckX(64, 16, groups=32, base_width=4, plugins=plugins)
    x = torch.randn(1, 64, 56, 56)
    x_out = block(x)
    assert x_out.shape == torch.Size([1, 64, 56, 56])

def test_resnext_backbone():
    with pytest.raises(KeyError):
        ResNeXt(depth=18)
    model = ResNeXt(depth=50, groups=32, base_width=4)
    for m in model.modules():
        if is_block(m):
            assert m.conv2.groups == 32
    model.train()
    imgs = torch.randn(1, 3, 32, 32)
    feat = model(imgs)
    assert len(feat) == 4
    assert feat[0].shape == torch.Size([1, 256, 8, 8])
    assert feat[1].shape == torch.Size([1, 512, 4, 4])
    assert feat[2].shape == torch.Size([1, 1024, 2, 2])
    assert feat[3].shape == torch.Size([1, 2048, 1, 1])

def test_mobilenetv2_backbone():
    with pytest.raises(ValueError):
        MobileNetV2(frozen_stages=8)
    with pytest.raises(ValueError):
        MobileNetV2(out_indices=[8])
    frozen_stages = 1
    model = MobileNetV2(frozen_stages=frozen_stages)
    model.train()
    for mod in model.conv1.modules():
        for param in mod.parameters():
            assert param.requires_grad is False
    for i in range(1, frozen_stages + 1):
        layer = getattr(model, f'layer{i}')
        for mod in layer.modules():
            if isinstance(mod, _BatchNorm):
                assert mod.training is False
        for param in layer.parameters():
            assert param.requires_grad is False
    model = MobileNetV2(norm_eval=True)
    model.train()
    assert check_norm_state(model.modules(), False)
    model = MobileNetV2(widen_factor=1.0, out_indices=range(0, 8))
    model.train()
    assert check_norm_state(model.modules(), True)
    imgs = torch.randn(1, 3, 224, 224)
    feat = model(imgs)
    assert len(feat) == 8
    assert feat[0].shape == torch.Size((1, 16, 112, 112))
    assert feat[1].shape == torch.Size((1, 24, 56, 56))
