@pytest.mark.parametrize('block', [BasicBlock, Bottleneck])
def test_hrmodule(block):
    num_channles = (32, 64)
    in_channels = [c * block.expansion for c in num_channles]
    hrmodule = HRModule(num_branches=2, blocks=block, in_channels=in_channels, num_blocks=(4, 4), num_channels=num_channles)
    feats = [torch.randn(1, in_channels[0], 64, 64), torch.randn(1, in_channels[1], 32, 32)]
    feats = hrmodule(feats)
    assert len(feats) == 2
    assert feats[0].shape == torch.Size([1, in_channels[0], 64, 64])
    assert feats[1].shape == torch.Size([1, in_channels[1], 32, 32])
    num_channles = (32, 64)
    in_channels = [c * block.expansion for c in num_channles]
    hrmodule = HRModule(num_branches=2, blocks=block, in_channels=in_channels, num_blocks=(4, 4), num_channels=num_channles, multiscale_output=False)
    feats = [torch.randn(1, in_channels[0], 64, 64), torch.randn(1, in_channels[1], 32, 32)]
    feats = hrmodule(feats)
    assert len(feats) == 1
    assert feats[0].shape == torch.Size([1, in_channels[0], 64, 64])

def test_hrnet_backbone():
    extra = dict(stage1=dict(num_modules=1, num_branches=1, block='BOTTLENECK', num_blocks=(4,), num_channels=(64,)), stage2=dict(num_modules=1, num_branches=2, block='BASIC', num_blocks=(4, 4), num_channels=(32, 64)), stage3=dict(num_modules=4, num_branches=3, block='BASIC', num_blocks=(4, 4, 4), num_channels=(32, 64, 128)))
    with pytest.raises(AssertionError):
        HRNet(extra=extra)
    extra['stage4'] = dict(num_modules=3, num_branches=3, block='BASIC', num_blocks=(4, 4, 4, 4), num_channels=(32, 64, 128, 256))
    with pytest.raises(AssertionError):
        HRNet(extra=extra)
    extra['stage4']['num_branches'] = 4
    model = HRNet(extra=extra)
    model.init_weights()
    model.train()
    imgs = torch.randn(1, 3, 256, 256)
    feats = model(imgs)
    assert len(feats) == 4
    assert feats[0].shape == torch.Size([1, 32, 64, 64])
    assert feats[3].shape == torch.Size([1, 256, 8, 8])
    model = HRNet(extra=extra, multiscale_output=False)
    model.init_weights()
    model.train()
    imgs = torch.randn(1, 3, 256, 256)
    feats = model(imgs)
    assert len(feats) == 1
    assert feats[0].shape == torch.Size([1, 32, 64, 64])

def test_hourglass_backbone():
    with pytest.raises(AssertionError):
        HourglassNet(num_stacks=0)
    with pytest.raises(AssertionError):
        HourglassNet(stage_channels=[256, 256, 384, 384, 384], stage_blocks=[2, 2, 2, 2, 2, 4])
    with pytest.raises(AssertionError):
        HourglassNet(downsample_times=5, stage_channels=[256, 256, 384, 384, 384], stage_blocks=[2, 2, 2, 2, 2])
    model = HourglassNet(num_stacks=1, stage_channels=(64, 64, 96, 96, 96, 128), feat_channel=64)
    model.train()
    imgs = torch.randn(1, 3, 256, 256)
    feat = model(imgs)
    assert len(feat) == 1
    assert feat[0].shape == torch.Size([1, 64, 64, 64])
    model = HourglassNet(num_stacks=2, stage_channels=(64, 64, 96, 96, 96, 128), feat_channel=64)
    model.train()
    imgs = torch.randn(1, 3, 256, 256)
    feat = model(imgs)
    assert len(feat) == 2
    assert feat[0].shape == torch.Size([1, 64, 64, 64])
    assert feat[1].shape == torch.Size([1, 64, 64, 64])

def test_resnest_bottleneck():
    with pytest.raises(AssertionError):
        BottleneckS(64, 64, radix=2, reduction_factor=4, style='tensorflow')
    block = BottleneckS(2, 4, radix=2, reduction_factor=4, stride=2, style='pytorch')
    assert block.avd_layer.stride == 2
    assert block.conv2.channels == 4
    block = BottleneckS(16, 4, radix=2, reduction_factor=4)
    x = torch.randn(2, 16, 56, 56)
    x_out = block(x)
    assert x_out.shape == torch.Size([2, 16, 56, 56])

def test_resnest_backbone():
    with pytest.raises(KeyError):
        ResNeSt(depth=18)
    model = ResNeSt(depth=50, base_channels=4, radix=2, reduction_factor=4, out_indices=(0, 1, 2, 3))
